module histories::whole_file;struct Writer<T>{run:server fn(str,T)->result<bool> !{task,fs};}
server fn save(path:str,data:bytes)->result<bool> !{task,fs}{task_yield();return file_write_bytes(path,data);}
server fn main()->i64 !{task,fs}{let writer:Writer<bytes>=Writer(save);let data:bytes=utf8_bytes("Привет 🧠");
return with_tasks(1,server fn(s:task_scope)->i64 !{task,fs}{let done:task<result<bool>>=task_spawn(s,server fn()->result<bool> !{task,fs}{return writer.run("output",data);});assert(unwrap(task_wait(done)));assert(unwrap(file_read_bytes("output"))==data);return 42;});}

client fn client_value()->i64{return 42;}
test fn pure_answer()->unit{assert(42>41);}

